function buildMsgText(ls) {
  return ls.map((l, i) => {
    const inc  = l.inc  ? '<code>' + l.inc  + '</code>' : '';
    const inet = l.inet ? '<code>' + l.inet + '</code>' : '';
    const odp  = l.odp  ? '<code>' + l.odp  + '</code>' : '';
    const tier = l.tier || '';
    const rest = l.rest || '';
    const parts = [inc, inet, odp, tier, rest].filter(Boolean);
    const lineStr = parts.join(' | ');
    const redStr = l.redaman !== null ? l.redaman : '<i>Belum diukur</i>';
    const snStr  = l.sn ? '\n   🔌 SN: <code>' + l.sn + '</code>' : '';
    let progStr;
    if (l.done) {
      progStr = '✅ <b>Selesai</b>';
      if (l.perbaikan) {
        progStr += ': <i>' + l.perbaikan + '</i>';
        if (l.penyebab) progStr += ' (<i>' + l.penyebab + '</i>)';
      }
    } else if (l.kendala) {
      progStr = '⚠️ <b>Kendala</b>';
      if (l.kendalaText) progStr += ': <i>' + l.kendalaText + '</i>';
    } else {
      progStr = '<i>Belum</i>';
    }
    if (l.done) {
      return (i+1) + '. ✅ <s>' + lineStr + '</s>\n   📡 ' + redStr + snStr + '\n   📋 Progres: ' + progStr;
    } else if (l.kendala) {
      return (i+1) + '. ⚠️ <i>' + lineStr + '</i>\n   📡 ' + redStr + snStr + '\n   📋 Progres: ' + progStr;
    } else {
      return (i+1) + '. ⏳ ' + lineStr + '\n   📡 ' + redStr + snStr + '\n   📋 Progres: ' + progStr;
    }
  }).join('\n\n') + '\n\n─────────────────';
}

function buildKeyboard(ls, sk) {
  const rows = [];
  ls.forEach((l, i) => {
    rows.push([
      { text: '📶 Ukur #'+(i+1)+(l.redaman!==null?' 🔁':''), callback_data:'u:'+i+':'+sk },
      { text: l.done    ? '↩️ Unmark #'+(i+1)        : '✅ Selesai #'+(i+1),   callback_data:'d:'+i+':'+sk },
      { text: l.kendala ? '↩️ Batal Kendala #'+(i+1) : '⚠️ Kendala #'+(i+1),  callback_data:'k:'+i+':'+sk }
    ]);
    rows.push([{ text: '📋 Rekap #'+(i+1), callback_data:'r:'+i+':'+sk }]);
  });
  rows.push([
    { text: '📡 Ukur Semua Redaman', callback_data:'a:'+sk },
    { text: '➕ Tambah Tiket',       callback_data:'add:'+sk }
  ]);
  return rows;
}

// ── Helper: ekstrak field via regex (support semua format) ────────────────
function extractFields(line) {
  const incM  = line.match(/\b(INC\d+)\b/i);
  const inetM = line.match(/\b(172\d{9,12})\b/);
  const odpM  = line.match(/\b(ODP-[A-Z0-9]+-[A-Z0-9\/\.]+)/i);
  const tierM = line.match(/\b(HVC_[A-Z_]+|REGULER|PREMIUM|SILVER|GOLD|PLATINUM)\b/i);
  if (!incM && !inetM) return null;
  return {
    inc:  incM  ? incM[1]  : '',
    inet: inetM ? inetM[1] : '',
    odp:  odpM  ? odpM[1]  : '',
    tier: tierM ? tierM[1] : '',
    rest: '',
    redaman: null, sn: null, done: false, kendala: false,
    perbaikan: null, penyebab: null, kendalaText: null
  };
}

function parseTicketText(text) {
  // ① Format WO resmi (label: value)
  const incM  = text.match(/NO TIKET\s*:\s*(INC\d+)/i);
  const inetM = text.match(/User Pelanggan\s*:\s*(172\d{9,12})/i) || text.match(/\b(172\d{9,12})\b/);
  const odpM  = text.match(/ODP Alpro\s*:\s*(ODP-[^\s\n\r]+)/i);
  const tierM = text.match(/Customer Type\s*:\s*([^\n\r]+)/i);
  if (incM) {
    return { inc:incM[1].trim(), inet:inetM?inetM[1].trim():'',
      odp:odpM?odpM[1].trim():'', tier:tierM?tierM[1].trim():'',
      rest:'', redaman:null, sn:null, done:false, kendala:false,
      perbaikan:null, penyebab:null, kendalaText:null };
  }
  // ② Format pipe-separated manual: INC | 172 | ODP | tier | rest
  const firstLine = text.split('\n')[0];
  const pipeParts = firstLine.split('|').map(p => p.trim());
  if (pipeParts.length >= 2 && pipeParts[0].match(/^INC\d+$/i)) {
    const inet2 = text.match(/\b(172\d{9,12})\b/);
    return { inc:pipeParts[0], inet:inet2?inet2[1]:(pipeParts[1]||''),
      odp:pipeParts[2]||'', tier:pipeParts[3]||'', rest:pipeParts.slice(4).join(' | '),
      redaman:null, sn:null, done:false, kendala:false,
      perbaikan:null, penyebab:null, kendalaText:null };
  }
  // ③ Format raw/space-delimited atau multi-baris bebas (scan seluruh teks)
  return extractFields(text);
}

function parseRedaman(resultRaw) {
  if (!resultRaw) return null;
  const onuStatusM = resultRaw.match(/<b>ONU status[^<]*<\/b>\s*([^\n<✅❌⚠️]+)/i);
  const onuRxM     = resultRaw.match(/<b>ONU rx[^<]*<\/b>\s*([-\d.]+)\s*dBm/i);
  const oltRxM     = resultRaw.match(/<b>OLT rx[^<]*<\/b>\s*([-\d.]+)\s*dBm/i);
  const status = onuStatusM ? onuStatusM[1].replace(/[✅❌⚠️🔁\s]+$/,'').trim() : '?';
  const onuRx  = onuRxM ? onuRxM[1]+' dBm' : '?';
  const oltRx  = oltRxM ? oltRxM[1]+' dBm' : '?';
  return 'St: <b>'+status+'</b> | ONU: <b>'+onuRx+'</b> | OLT: <b>'+oltRx+'</b>';
}

const msg    = $input.first().json;
const text   = msg.message?.text || '';
const chatId = String(msg.message?.chat?.id || '');
const userMsgId = String(msg.message?.message_id || '');
if (!text.trim() || !chatId) return [];

const sd = $getWorkflowStaticData('global');

// ── 1. Pending keterangan ─────────────────────────────────────────────────
const pk = sd['_pending_keterangan'];
if (pk && String(pk.chatId) === chatId) {
  const input   = text.trim();
  const session = sd[pk.sessionKey];
  if (!session) { delete sd['_pending_keterangan']; return []; }
  const sessionKey = pk.sessionKey;

  if (pk.step === 'perbaikan') {
    delete sd['_pending_keterangan'];
    const perbaikan = input.replace(/\s*\(.*\)\s*$/, '').trim();
    const penyebabMatch = input.match(/\(([^)]+)\)/);
    const penyebab = penyebabMatch ? penyebabMatch[1].trim() : '';
    sd[sessionKey].lines[pk.lineIndex].done      = true;
    sd[sessionKey].lines[pk.lineIndex].kendala   = false;
    sd[sessionKey].lines[pk.lineIndex].perbaikan = perbaikan;
    sd[sessionKey].lines[pk.lineIndex].penyebab  = penyebab;
    return [{ json: {
      _tg_action:       'edit_after_input',
      delete_prompt_id:  pk.promptMsgId || null,
      delete_user_id:    userMsgId,
      notify_cb_id:      pk.callbackQueryId || null,
      notify_text:       '✅ Tiket #'+(pk.lineIndex+1)+' ditandai Selesai!',
      tg_chat_id:        session.chatId,
      tg_method:         'editMessageText',
      chat_id:           session.chatId,
      message_id:        parseInt(session.messageId),
      text:              buildMsgText(sd[sessionKey].lines),
      parse_mode:        'HTML',
      reply_markup:      JSON.stringify({inline_keyboard:buildKeyboard(sd[sessionKey].lines,sessionKey)})
    }}];
  }

  if (pk.step === 'penyebab') {
    delete sd['_pending_keterangan'];
    sd[sessionKey].lines[pk.lineIndex].done      = true;
    sd[sessionKey].lines[pk.lineIndex].kendala   = false;
    sd[sessionKey].lines[pk.lineIndex].perbaikan = pk.perbaikan;
    sd[sessionKey].lines[pk.lineIndex].penyebab  = input;
    return [{ json: {
