      tg_chat_id:        session.chatId,
      tg_method:         'editMessageText',
      chat_id:           session.chatId,
      message_id:        parseInt(session.messageId),
      text:              buildMsgText(sd[sessionKey].lines),
      parse_mode:        'HTML',
      reply_markup:      JSON.stringify({inline_keyboard:buildKeyboard(sd[sessionKey].lines,sessionKey)})
    }}];
  }

  if (pk.step === 'kendala') {
    delete sd['_pending_keterangan'];
    sd[sessionKey].lines[pk.lineIndex].kendala    = true;
    sd[sessionKey].lines[pk.lineIndex].done       = false;
    sd[sessionKey].lines[pk.lineIndex].kendalaText = input;
    return [{ json: {
      _tg_action:       'edit_after_input',
      delete_prompt_id:  pk.promptMsgId || null,
      delete_user_id:    userMsgId,
      notify_cb_id:      pk.callbackQueryId || null,
