        perbaikan:null, penyebab:null, kendalaText:null };
    }
    // Fallback: regex extraction (format space-delimited / raw system dump)
    return extractFields(line) || {
      inc:line.trim().substring(0,50), inet:'', odp:'', tier:'', rest:'',
      redaman:null, sn:null, done:false, kendala:false,
      perbaikan:null, penyebab:null, kendalaText:null
    };
