if (!pending || pending.length === 0) return [];
const sessionKey = pending[0].sessionKey;
const session    = sd[sessionKey];
if (!session) return [];

let successCount = 0;
const failList   = [];
const matched    = new Set();

// Iterasi semua items dari sub-workflow
// Mode 'each': tiap item = 1 sub-execution result
// Error item: item.json mungkin ada error field, atau result_text null
for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  // Handle error items dari continueOnFail
  if (!item || !item.json) continue;

  const result = item.json;
  // Cek apakah ini error item (sub-workflow gagal)
  const isError = result.error !== undefined || (!result.result_text && !result.onu_sn);
  if (isError) continue;  // akan di-handle sebagai unmatched = gagal

  const rt = result.result_text || '';
  if (!rt) continue;

  // Extract inet dari result_text: "nomor internet 172418XXXXXX"
  const inetM = rt.match(/nomor internet\s+(\d+)/i);
  if (!inetM) continue;
  const inet = inetM[1];

  // Cari pending item yang sesuai
  const pidx = pending.findIndex((p, i) =>
    !matched.has(i) &&
    String(sd[sessionKey]?.lines[p.lineIndex]?.inet || '') === inet
  );
  if (pidx < 0) continue;

  matched.add(pidx);
  const redaman = parseRedaman(rt) || '⚠️ No data';
  sd[sessionKey].lines[pending[pidx].lineIndex].redaman = redaman;
  if (result.onu_sn) sd[sessionKey].lines[pending[pidx].lineIndex].sn = result.onu_sn;
  successCount++;
}

