for (let i = 0; i < pending.length; i++) {
  if (!matched.has(i)) {
    const label = sd[sessionKey].lines[pending[i].lineIndex]?.inet
      || ('baris #'+(pending[i].lineIndex+1));
    sd[sessionKey].lines[pending[i].lineIndex].redaman = '⚠️ Gagal';
    failList.push(label);
  }
}

delete sd['_pending_all'];

const total      = pending.length;
const summaryTxt = failList.length === 0
  ? '✅ Semua '+total+' redaman berhasil diukur!'
  : '⚠️ '+successCount+'/'+total+' berhasil. Gagal: '+failList.join(', ');

